// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/terminal/parts.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * What the terminal pages' scenes share: a captured Claude Code screen with
 * parts of its text marked the way xterm draws them (a hovered link's
 * underline, the find decorations), a session tile around one, and the box
 * the app's portaled overlays (menus, dialogs, the drop overlay) sit in.
 */
import { useMemo, useSyncExternalStore, type CSSProperties, type ReactNode, type RefObject } from "react";
import { Term, Tile, type Stat } from "../../home/AppUI";
import { parseAnsi, TerminalLines, type Run, type TerminalRow } from "../../home/ansi";
import { CAPTURES, type CaptureId } from "../../home/captures";
import { THIS_MAC } from "../../home/Chrome";
import { SESSIONS, type SessionId } from "../../home/Scenes";

/* ------------------------------------------------------- terminal text -- */

// False while rendering on the server and hydrating, true once in the
// browser: the captures are drawn client-side only, like AnsiScreen.
const noSubscription = () => () => {};
const useInBrowser = () => useSyncExternalStore(noSubscription, () => true, () => false);

/** A capture as lines of styled runs, parsed once in the browser. */
export function useCapture(id: CaptureId): Run[][] {
  const inBrowser = useInBrowser();
  return useMemo(() => (inBrowser ? parseAnsi(CAPTURES[id]) : []), [inBrowser, id]);
}

/** A line's text as the terminal shows it. */
export const plainText = (runs: Run[]) => runs.map((run) => run.text).join("");

/** A span of one line drawn with extra cell styling (an underline, a find decoration). */
export interface Mark {
  line: number;
  start: number;
  end: number;
  style: Run["style"];
}

/** Splits a line's runs at the marks' edges and lays each mark's style over its cells. */
function markRuns(runs: Run[], marks: Mark[]): Run[] {
  if (!marks.length) return runs;
  const edges = [...new Set(marks.flatMap((mark) => [mark.start, mark.end]))].sort((a, b) => a - b);
  const out: Run[] = [];
  let offset = 0;
  for (const run of runs) {
    const end = offset + run.text.length;
    let from = offset;
    for (const to of [...edges.filter((edge) => edge > offset && edge < end), end]) {
      const mark = marks.find((item) => from >= item.start && from < item.end);
      out.push({ text: run.text.slice(from - offset, to - offset), style: mark ? { ...run.style, ...mark.style } : run.style });
      from = to;
    }
    offset = end;
  }
  return out;
}

/** Where `text` sits in a capture: its first line containing it, from `after` on. */
export function locate(lines: Run[][], text: string, after = 0): Mark | null {
  for (let line = after; line < lines.length; line += 1) {
    const start = plainText(lines[line]).indexOf(text);
    if (start >= 0) return { line, start, end: start + text.length, style: {} };
  }
  return null;
}

/** A captured screen with `marks` drawn over its text, cell for cell like AnsiScreen. */
export function MarkedScreen({ lines, marks }: { lines: Run[][]; marks: Mark[] }) {
  const rows: TerminalRow[] = lines.map((runs, line) => ({ runs: markRuns(runs, marks.filter((mark) => mark.line === line)) }));
  return <TerminalLines rows={rows} />;
}

/* ----------------------------------------------------------------- tile -- */

/** A tile running one of the captured Claude Code sessions, with its own terminal content. */
export function CaptureTile({ id, kbd, stat, children }: { id: SessionId; kbd: string; stat?: Stat; children: ReactNode }) {
  const { path, started } = SESSIONS[id];
  return (
    <Tile title={id} agent="claude" stat={stat} kbd={kbd} device={THIS_MAC} strip={{ session: id, branch: "main", path, started }}>
      <Term>{children}</Term>
    </Tile>
  );
}

/* ------------------------------------------------------------- viewport -- */

type CssVars = CSSProperties & { [name: `--${string}`]: string };

/**
 * The window's own box as the viewport. The app portals menus, dialogs and
 * overlays to <body> and places them with `position: fixed`, so in the app
 * they sit against the window. Here the window is a box inside the scene,
 * so this layer (transformed, which makes it the containing block of fixed
 * descendants) stands in for the viewport: fixed app elements inside it are
 * placed against the window and clipped by its corners, and viewport units
 * (--pz-vh / --pz-vw in app.css) resolve to the window's size. `z` is the
 * overlay's own z-index in the app, so it stacks over the top bar as there;
 * `passThrough` lets presses reach the tiles where the overlay has no box.
 */
export function Viewport({
  width,
  height,
  z,
  passThrough = false,
  viewportRef,
  children,
}: {
  width: number;
  height: number;
  z: number;
  passThrough?: boolean;
  /** For a scene that maps a pointer position into window coordinates. */
  viewportRef?: RefObject<HTMLDivElement>;
  children?: ReactNode;
}) {
  const style: CssVars = {
    position: "absolute",
    inset: 0,
    zIndex: z,
    transform: "translateZ(0)",
    pointerEvents: passThrough ? "none" : undefined,
    "--pz-vh": `${height / 100}px`,
    "--pz-vw": `${width / 100}px`,
  };
  return (
    <div ref={viewportRef} style={style}>
      {children}
    </div>
  );
}
